1	package com.example.starter.compliance.service;
2	
3	import com.example.starter.compliance.ApiException;
4	import com.example.starter.compliance.domain.DirectAdditive;
5	import com.example.starter.compliance.domain.FormulaContent;
6	import com.example.starter.compliance.domain.IngredientUse;
7	import com.example.starter.compliance.engine.LimitEngine;
8	import com.example.starter.compliance.engine.ReviewInput;
9	import com.example.starter.compliance.engine.ReviewModels.ReviewReport;
10	import com.example.starter.compliance.repo.AdditiveRow;
11	import com.example.starter.compliance.repo.ComplianceRepository;
12	import com.example.starter.compliance.repo.FilingRow;
13	import com.example.starter.compliance.repo.FormulaRow;
14	import com.example.starter.compliance.repo.IngredientAdditiveRow;
15	import com.example.starter.compliance.repo.LimitRow;
16	import com.example.starter.compliance.support.JsonSupport;
17	import com.example.starter.compliance.time.ComplianceClock;
18	import com.example.starter.compliance.web.Requests.FileFilingRequest;
19	import com.example.starter.compliance.web.Requests.FilingRefRequest;
20	import com.example.starter.compliance.web.Requests.FormulaRefRequest;
21	import com.example.starter.compliance.web.Requests.ProductionReportRequest;
22	import com.example.starter.compliance.web.Requests.StandardUpdateRequest;
23	import com.example.starter.compliance.web.Requests.SubmitFormulaRequest;
24	import java.math.BigDecimal;
25	import java.nio.charset.StandardCharsets;
26	import java.security.MessageDigest;
27	import java.security.NoSuchAlgorithmException;
28	import java.util.ArrayList;
29	import java.util.HexFormat;
30	import java.util.LinkedHashMap;
31	import java.util.List;
32	import java.util.Map;
33	import java.util.Optional;
34	import java.util.Set;
35	import java.util.TreeMap;
36	import java.util.function.Supplier;
37	import java.util.stream.Collectors;
38	import org.springframework.dao.DuplicateKeyException;
39	import org.springframework.http.HttpStatus;
40	import org.springframework.stereotype.Service;
41	import org.springframework.transaction.annotation.Transactional;
42	
43	/**
44	 * 配方合规领域服务。
45	 *
46	 * <p>状态机：配方 SUBMITTED → REVIEWED（审查通过）→ APPROVED（批准并冻结版本快照）；
47	 * 批准新版本时在同一事务内暂停同产品旧有效备案，随后可对批准版本做量产备案（ACTIVE）。
48	 * 标准更新后受影响备案进入 REVIEW_WATCH，90 个 UTC 自然日内（恰第 90 日受理）复审，
49	 * 逾期自动暂停；注销为终态，注销后量产上报一律拒绝。
50	 *
51	 * <p>所有变更接口以 requestId 幂等：指纹覆盖 requestId 与全部业务字段，同键同参重放首次结果，
52	 * 同键异参返回 409。
53	 */
54	@Service
55	public class ComplianceService {
56	
57	    /** 复审观察期限（UTC 自然日），截止日 = 观察起始日 + 90，恰第 90 日提交仍受理。 */
58	    public static final long REVIEW_GRACE_DAYS = 90L;
59	
60	    private final ComplianceRepository repository;
61	    private final ComplianceClock clock;
62	    private final LimitEngine engine;
63	    private final FilingTransitions transitions;
64	
65	    public ComplianceService(ComplianceRepository repository, ComplianceClock clock,
66	            LimitEngine engine, FilingTransitions transitions) {
67	        this.repository = repository;
68	        this.clock = clock;
69	        this.engine = engine;
70	        this.transitions = transitions;
71	    }
72	
73	    // ---------------- 配方：提交 / 审查 / 批准 ----------------
74	
75	    @Transactional
76	    public ServiceResult<Results.FormulaView> submitFormula(SubmitFormulaRequest request) {
77	        return withIdempotency(request.requestId(), request, Results.FormulaView.class, () -> {
78	            FormulaContent content = validateAndBuild(request);
79	            if (repository.findFormula(content.productCode(), content.version()).isPresent()) {
80	                throw new ApiException(HttpStatus.CONFLICT, "FORMULA_VERSION_EXISTS",
81	                        "同一产品版本已存在：" + content.productCode() + "#" + content.version());
82	            }
83	            long now = clock.nowMillis();
84	            long formulaId = repository.insertFormula(content, "SUBMITTED", now);
85	            for (DirectAdditive additive : content.additives()) {
86	                repository.insertDirectAdditive(formulaId, additive.additiveCode(),
87	                        additive.amount());
88	            }
89	            for (IngredientUse use : content.ingredients()) {
90	                repository.insertIngredientUse(formulaId, use.ingredientCode(), use.ratio());
91	            }
92	            FormulaRow row = repository.findFormulaById(formulaId).orElseThrow();
93	            return new Outcome<>(buildFormulaView(row, false), HttpStatus.OK.value());
94	        });
95	    }
96	
97	    @Transactional
98	    public ServiceResult<Results.ReviewView> reviewFormula(FormulaRefRequest request) {
99	        return withIdempotency(request.requestId(), request, Results.ReviewView.class, () -> {
100	            FormulaRow formula = requireFormula(request.formulaId());
101	            if ("APPROVED".equals(formula.state())) {
102	                throw new ApiException(HttpStatus.CONFLICT, "FORMULA_FROZEN",
103	                        "配方批准后版本冻结，不能再次审查");
104	            }
105	            ReviewReport report = evaluateFormula(formula);
106	            // 整单判定：通过进入 REVIEWED；任一违例保持 SUBMITTED，不产生批准/备案等部分后续记录。
107	            repository.markReviewed(formula.id(), report.passed(), JsonSupport.write(report),
108	                    clock.nowMillis());
109	            FormulaRow refreshed = repository.findFormulaById(formula.id()).orElseThrow();
110	            return new Outcome<>(
111	                    new Results.ReviewView(refreshed.id(), refreshed.state(), report, false),
112	                    HttpStatus.OK.value());
113	        });
114	    }
115	
116	    @Transactional
117	    public ServiceResult<Results.FormulaView> approveFormula(FormulaRefRequest request) {
118	        return withIdempotency(request.requestId(), request, Results.FormulaView.class, () -> {
119	            FormulaRow formula = requireFormula(request.formulaId());
120	            if ("APPROVED".equals(formula.state())) {
121	                return new Outcome<>(buildFormulaView(formula, false), HttpStatus.OK.value());
122	            }
123	            if (!"REVIEWED".equals(formula.state()) || !Boolean.TRUE.equals(formula.reviewPassed())) {
124	                throw new ApiException(HttpStatus.CONFLICT, "REVIEW_NOT_PASSED",
125	                        "配方尚未通过合规审查，不能批准");
126	            }
127	            ReviewReport report = JsonSupport.read(formula.reviewJson(), ReviewReport.class);
128	            FormulaContent content = loadContent(formula);
129	            Map<String, LimitRow> limits = loadCurrentLimits(formula.categoryCode());
130	            ApprovedSnapshot snapshot = new ApprovedSnapshot(content, limits, report,
131	                    clock.nowMillis());
132	            String snapshotJson = JsonSupport.write(snapshot);
133	            repository.markApproved(formula.id(), snapshotJson, clock.nowMillis());
134	
135	            // 新版本批准与旧版本备案暂停同一事务完成，保证任何时刻不出现双有效版本。
136	            for (FilingRow old : repository.findEffectiveFilingsByProduct(formula.productCode())) {
137	                repository.markSuspended(old.id(), "SUPERSEDED", clock.nowMillis());
138	                repository.releaseProduct(formula.productCode());
139	            }
140	
141	            FormulaRow refreshed = repository.findFormulaById(formula.id()).orElseThrow();
142	            return new Outcome<>(buildFormulaView(refreshed, false), HttpStatus.OK.value());
143	        });
144	    }
145	
146	    // ---------------- 量产备案 / 注销 / 复审 ----------------
147	
148	    @Transactional
149	    public ServiceResult<Results.FilingView> fileFiling(FileFilingRequest request) {
150	        return withIdempotency(request.requestId(), request, Results.FilingView.class, () -> {
151	            FormulaRow formula = requireFormula(request.formulaId());
152	            if (!"APPROVED".equals(formula.state())) {
153	                throw new ApiException(HttpStatus.CONFLICT, "FORMULA_NOT_APPROVED",
154	                        "仅批准版本可量产备案");
155	            }
156	            Optional<FilingRow> existing = repository.findFilingByFormulaId(formula.id());
157	            if (existing.isPresent()) {
158	                throw new ApiException(HttpStatus.CONFLICT, "FILING_EXISTS",
159	                        "该批准版本已存在备案：filingId=" + existing.get().id());
160	            }
161	            List<FilingRow> effective =
162	                    repository.findEffectiveFilingsByProduct(formula.productCode());
163	            if (!effective.isEmpty()) {
164	                throw new ApiException(HttpStatus.CONFLICT, "FILING_VERSION_CONFLICT",
165	                        "同一产品存在有效备案版本，禁止重复有效备案");
166	            }
167	            long now = clock.nowMillis();
168	            long filingId = repository.insertFiling(formula.id(), formula.productCode(),
169	                    formula.version(), "ACTIVE", request.requestId(),
170	                    formula.approvedSnapshot(), now);
171	            try {
172	                repository.tryOccupyProduct(formula.productCode(), filingId);
173	            } catch (DuplicateKeyException e) {
174	                // 并发备案：唯一有效位冲突，整事务回滚，仅一方成功。
175	                throw new ApiException(HttpStatus.CONFLICT, "FILING_VERSION_CONFLICT",
176	                        "并发备案冲突，同一产品仅允许一个有效备案版本");
177	            }
178	            FilingRow row = repository.findFilingById(filingId).orElseThrow();
179	            return new Outcome<>(buildFilingView(row, false), HttpStatus.OK.value());
180	        });
181	    }
182	
183	    @Transactional
184	    public ServiceResult<Results.FilingView> cancelFiling(FilingRefRequest request) {
185	        return withIdempotency(request.requestId(), request, Results.FilingView.class, () -> {
186	            FilingRow filing = requireFiling(request.filingId());
187	            // 注销为终态：重复注销返回幂等成功。
188	            if (!"CANCELLED".equals(filing.status())) {
189	                repository.markCancelled(filing.id(), clock.nowMillis());
190	                repository.releaseProduct(filing.productCode());
191	            }
192	            FilingRow refreshed = repository.findFilingById(filing.id()).orElseThrow();
193	            return new Outcome<>(buildFilingView(refreshed, false), HttpStatus.OK.value());
194	        });
195	    }
196	
197	    @Transactional
198	    public ServiceResult<Results.FilingReviewView> reviewFiling(FilingRefRequest request) {
199	        return withIdempotency(request.requestId(), request, Results.FilingReviewView.class, () -> {
200	            FilingRow filing = requireFiling(request.filingId());
201	            long today = clock.todayEpochDay();
202	            if ("CANCELLED".equals(filing.status())) {
203	                throw new ApiException(HttpStatus.GONE, "FILING_CANCELLED",
204	                        "备案已注销，不能复审");
205	            }
206	            if (filing.watchStartDay() == null || !"REVIEW_WATCH".equals(filing.status())) {
207	                throw new ApiException(HttpStatus.CONFLICT, "FILING_NOT_IN_WATCH",
208	                        "备案未进入复审观察，无需复审");
209	            }
210	            long deadline = filing.watchStartDay() + REVIEW_GRACE_DAYS;
211	            if (today > deadline) {
212	                // 逾期未复审：独立事务立即暂停并释放有效位；首次结果记 409 并落幂等记录，
213	                // 同一 requestId 重放返回相同 409 结果。
214	                transitions.suspendOverdueNewTransaction(filing);
215	                FilingRow suspended = repository.findFilingById(filing.id()).orElseThrow();
216	                return new Outcome<>(new Results.FilingReviewView(suspended.id(),
217	                        suspended.status(), false, null, clock.nowMillis(), false),
218	                        HttpStatus.CONFLICT.value());
219	            }
220	
221	            // 按批准版本冻结快照复算，但限量取当前最新标准。
222	            ApprovedSnapshot snapshot =
223	                    JsonSupport.read(filing.snapshot(), ApprovedSnapshot.class);
224	            ReviewInput input = buildInput(snapshot.content(),
225	                    loadCurrentLimits(snapshot.content().categoryCode()));
226	            ReviewReport report = engine.evaluate(input, clock.nowMillis());
227	            boolean passed = report.passed();
228	            if (passed) {
229	                repository.markActive(filing.id());
230	            } else {
231	                repository.markSuspended(filing.id(), "REVIEW_FAILED", clock.nowMillis());
232	                repository.releaseProduct(filing.productCode());
233	            }
234	            repository.insertFilingReview(filing.id(), request.requestId(), passed,
235	                    JsonSupport.write(report), clock.nowMillis());
236	            FilingRow refreshed = repository.findFilingById(filing.id()).orElseThrow();
237	            return new Outcome<>(new Results.FilingReviewView(refreshed.id(),
238	                    refreshed.status(), passed, report, clock.nowMillis(), false),
239	                    HttpStatus.OK.value());
240	        });
241	    }
242	
243	    @Transactional
244	    public ServiceResult<Results.ProductionView> reportProduction(ProductionReportRequest request) {
245	        return withIdempotency(request.requestId(), request, Results.ProductionView.class, () -> {
246	            if (request.batchNo() == null || request.batchNo().isBlank()) {
247	                throw invalid("批次号不能为空");
248	            }
249	            if (request.quantityKg() == null || request.quantityKg().signum() < 0) {
250	                throw invalid("量产数量必须为非负数");
251	            }
252	            FilingRow filing = requireFiling(request.filingId());
253	            long today = clock.todayEpochDay();
254	            if ("CANCELLED".equals(filing.status())) {
255	                throw new ApiException(HttpStatus.GONE, "FILING_CANCELLED",
256	                        "备案已注销，量产记录上报一律拒绝");
257	            }
258	            if ("SUSPENDED".equals(filing.status())) {
259	                throw new ApiException(HttpStatus.CONFLICT, "FILING_SUSPENDED",
260	                        "备案已暂停，量产记录上报拒绝");
261	            }
262	            if ("REVIEW_WATCH".equals(filing.status())
263	                    && today > filing.watchStartDay() + REVIEW_GRACE_DAYS) {
264	                // 逾期未复审：独立事务立即暂停备案；量产记录不写入，首次结果记 409 并落幂等记录。
265	                transitions.suspendOverdueNewTransaction(filing);
266	                FilingRow suspended = repository.findFilingById(filing.id()).orElseThrow();
267	                return new Outcome<>(new Results.ProductionView(suspended.id(), request.batchNo(),
268	                        null, clock.nowMillis(), false), HttpStatus.CONFLICT.value());
269	            }
270	            long now = clock.nowMillis();
271	            repository.insertProductionRecord(filing.id(), request.batchNo(),
272	                    request.quantityKg(), now);
273	            return new Outcome<>(new Results.ProductionView(filing.id(), request.batchNo(),
274	                    request.quantityKg().stripTrailingZeros().toPlainString(), now, false),
275	                    HttpStatus.OK.value());
276	        });
277	    }
278	
279	    // ---------------- 标准更新 / 逾期巡检 / 查询 ----------------
280	
281	    @Transactional
282	    public ServiceResult<Results.StandardView> updateStandard(StandardUpdateRequest request) {
283	        return withIdempotency(request.requestId(), request, Results.StandardView.class, () -> {
284	            if (request.additiveCode() == null || request.additiveCode().isBlank()) {
285	                throw invalid("添加剂编码不能为空");
286	            }
287	            if (request.categoryCode() == null || request.categoryCode().isBlank()) {
288	                throw invalid("食品分类编码不能为空");
289	            }
290	            if (request.maxAmount() == null || request.maxAmount().signum() <= 0) {
291	                throw invalid("最大使用量必须为正数");
292	            }
293	            if (repository.findAdditive(request.additiveCode()).isEmpty()) {
294	                throw new ApiException(HttpStatus.BAD_REQUEST, "ADDITIVE_NOT_FOUND",
295	                        "添加剂目录中不存在：" + request.additiveCode());
296	            }
297	            if (!repository.categoryExists(request.categoryCode())) {
298	                throw new ApiException(HttpStatus.BAD_REQUEST, "CATEGORY_NOT_FOUND",
299	                        "食品分类不存在：" + request.categoryCode());
300	            }
301	            long now = clock.nowMillis();
302	            Optional<LimitRow> current =
303	                    repository.findLimit(request.additiveCode(), request.categoryCode());
304	            if (current.isPresent()) {
305	                repository.updateLimit(request.additiveCode(), request.categoryCode(),
306	                        request.maxAmount(), now);
307	            } else {
308	                repository.insertLimit(request.additiveCode(), request.categoryCode(),
309	                        request.maxAmount(), now);
310	            }
311	
312	            // 标准更新后，受影响的旧版本已备案配方进入复审观察（保留最早起始日，不延长 90 日期限）。
313	            List<Long> watchIds = new ArrayList<>();
314	            for (FilingRow filing : repository.findFilingsAffectedByStandard(
315	                    request.categoryCode(), request.additiveCode())) {
316	                repository.markReviewWatch(filing.id(), clock.todayEpochDay());
317	                watchIds.add(filing.id());
318	            }
319	            return new Outcome<>(new Results.StandardView(request.additiveCode(),
320	                    request.categoryCode(),
321	                    request.maxAmount().stripTrailingZeros().toPlainString(), now,
322	                    List.copyOf(watchIds), false), HttpStatus.OK.value());
323	        });
324	    }
325	
326	    /** 逾期巡检：复审观察超过第 90 个 UTC 自然日仍未复审的备案自动暂停并释放有效位。 */
327	    @Transactional
328	    public Results.SweepView sweepOverdue() {
329	        long today = clock.todayEpochDay();
330	        List<Long> suspended = new ArrayList<>();
331	        for (FilingRow filing : repository.findReviewWatchFilings()) {
332	            if (today > filing.watchStartDay() + REVIEW_GRACE_DAYS) {
333	                suspendOverdue(filing);
334	                suspended.add(filing.id());
335	            }
336	        }
337	        return new Results.SweepView(today, List.copyOf(suspended));
338	    }
339	
340	    @Transactional(readOnly = true)
341	    public Results.FormulaView getFormula(long formulaId) {
342	        return buildFormulaView(requireFormula(formulaId), false);
343	    }
344	
345	    @Transactional(readOnly = true)
346	    public Results.FilingView getFiling(long filingId) {
347	        return buildFilingView(requireFiling(filingId), false);
348	    }
349	
350	    @Transactional(readOnly = true)
351	    public Results.TrajectoryView getTrajectory(String productCode) {
352	        List<Results.FormulaView> formulas =
353	                repository.findFormulaVersionsByProduct(productCode).stream()
354	                        .map(row -> buildFormulaView(row, false))
355	                        .toList();
356	        List<Results.FilingView> filings = repository.findFilingsByProduct(productCode).stream()
357	                .map(row -> buildFilingView(row, false))
358	                .toList();
359	        return new Results.TrajectoryView(productCode, formulas, filings);
360	    }
361	
362	    // ---------------- 内部辅助 ----------------
363	
364	    private void suspendOverdue(FilingRow filing) {
365	        repository.markSuspended(filing.id(), "OVERDUE", clock.nowMillis());
366	        repository.releaseProduct(filing.productCode());
367	    }
368	
369	    private FormulaRow requireFormula(Long formulaId) {
370	        if (formulaId == null) {
371	            throw invalid("formulaId 不能为空");
372	        }
373	        return repository.findFormulaById(formulaId)
374	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "FORMULA_NOT_FOUND",
375	                        "配方不存在：" + formulaId));
376	    }
377	
378	    private FilingRow requireFiling(Long filingId) {
379	        if (filingId == null) {
380	            throw invalid("filingId 不能为空");
381	        }
382	        return repository.findFilingById(filingId)
383	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "FILING_NOT_FOUND",
384	                        "备案不存在：" + filingId));
385	    }
386	
387	    private static ApiException invalid(String message) {
388	        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_PARAM", message);
389	    }
390	
391	    private FormulaContent validateAndBuild(SubmitFormulaRequest request) {
392	        if (request.productCode() == null || request.productCode().isBlank()) {
393	            throw invalid("产品编码不能为空");
394	        }
395	        if (request.productName() == null || request.productName().isBlank()) {
396	            throw invalid("产品名称不能为空");
397	        }
398	        if (request.categoryCode() == null || request.categoryCode().isBlank()) {
399	            throw invalid("食品分类编码不能为空");
400	        }
401	        if (!repository.categoryExists(request.categoryCode())) {
402	            throw new ApiException(HttpStatus.BAD_REQUEST, "CATEGORY_NOT_FOUND",
403	                    "食品分类不存在：" + request.categoryCode());
404	        }
405	        if (request.version() == null || request.version() < 1) {
406	            throw invalid("版本号必须为正整数");
407	        }
408	
409	        List<DirectAdditive> additives = new ArrayList<>();
410	        for (var dto : nullToEmpty(request.additives())) {
411	            if (dto.additiveCode() == null || dto.additiveCode().isBlank()) {
412	                throw invalid("添加剂编码不能为空");
413	            }
414	            if (repository.findAdditive(dto.additiveCode()).isEmpty()) {
415	                throw new ApiException(HttpStatus.BAD_REQUEST, "ADDITIVE_NOT_FOUND",
416	                        "添加剂目录中不存在：" + dto.additiveCode());
417	            }
418	            if (dto.amount() == null || dto.amount().signum() < 0) {
419	                throw invalid("添加剂用量必须为非负数：" + dto.additiveCode());
420	            }
421	            additives.add(new DirectAdditive(dto.additiveCode(), dto.amount()));
422	        }
423	
424	        List<IngredientUse> ingredients = new ArrayList<>();
425	        for (var dto : nullToEmpty(request.ingredients())) {
426	            if (dto.ingredientCode() == null || dto.ingredientCode().isBlank()) {
427	                throw invalid("复合配料编码不能为空");
428	            }
429	            if (!repository.ingredientExists(dto.ingredientCode())) {
430	                throw new ApiException(HttpStatus.BAD_REQUEST, "INGREDIENT_NOT_FOUND",
431	                        "复合配料目录中不存在：" + dto.ingredientCode());
432	            }
433	            if (dto.ratio() == null || dto.ratio().signum() < 0
434	                    || dto.ratio().compareTo(BigDecimal.ONE) > 0) {
435	                throw invalid("配料占比必须在 0~1 之间：" + dto.ingredientCode());
436	            }
437	            ingredients.add(new IngredientUse(dto.ingredientCode(), dto.ratio()));
438	        }
439	
440	        return new FormulaContent(request.productCode(), request.productName(),
441	                request.categoryCode(), request.version(), List.copyOf(additives),
442	                List.copyOf(ingredients));
443	    }
444	
445	    private static <T> List<T> nullToEmpty(List<T> list) {
446	        return list == null ? List.of() : list;
447	    }
448	
449	    private FormulaContent loadContent(FormulaRow formula) {
450	        return new FormulaContent(formula.productCode(), formula.productName(),
451	                formula.categoryCode(), formula.version(),
452	                repository.findDirectAdditives(formula.id()),
453	                repository.findIngredientUses(formula.id()));
454	    }
455	
456	    private Map<String, LimitRow> loadCurrentLimits(String categoryCode) {
457	        Map<String, LimitRow> limits = new LinkedHashMap<>();
458	        for (LimitRow row : repository.findLimitsByCategory(categoryCode)) {
459	            limits.put(row.additiveCode(), row);
460	        }
461	        return limits;
462	    }
463	
464	    private ReviewReport evaluateFormula(FormulaRow formula) {
465	        FormulaContent content = loadContent(formula);
466	        return engine.evaluate(buildInput(content, loadCurrentLimits(content.categoryCode())),
467	                clock.nowMillis());
468	    }
469	
470	    private ReviewInput buildInput(FormulaContent content, Map<String, LimitRow> limits) {
471	        Map<String, AdditiveRow> catalog = new TreeMap<>();
472	        for (DirectAdditive additive : content.additives()) {
473	            AdditiveRow row = repository.findAdditive(additive.additiveCode())
474	                    .orElseThrow(() -> new ApiException(HttpStatus.BAD_REQUEST,
475	                            "ADDITIVE_NOT_FOUND", "添加剂目录中不存在：" + additive.additiveCode()));
476	            catalog.put(row.code(), row);
477	        }
478	
479	        List<String> ingredientCodes = content.ingredients().stream()
480	                .map(IngredientUse::ingredientCode)
481	                .distinct()
482	                .toList();
483	        List<IngredientAdditiveRow> carriedRows =
484	                repository.findIngredientAdditives(ingredientCodes);
485	        Map<String, List<IngredientAdditiveRow>> byIngredient = carriedRows.stream()
486	                .collect(Collectors.groupingBy(IngredientAdditiveRow::ingredientCode,
487	                        LinkedHashMap::new, Collectors.toList()));
488	        for (IngredientAdditiveRow row : carriedRows) {
489	            repository.findAdditive(row.additiveCode()).ifPresent(additive ->
490	                    catalog.putIfAbsent(additive.code(), additive));
491	        }
492	
493	        Set<String> knownIngredients = Set.copyOf(ingredientCodes);
494	        return new ReviewInput(content.categoryCode(), content.additives(),
495	                content.ingredients(), catalog, knownIngredients, byIngredient, limits);
496	    }
497	
498	    private Results.FormulaView buildFormulaView(FormulaRow row, boolean replayed) {
499	        ReviewReport report = row.reviewJson() == null ? null
500	                : JsonSupport.read(row.reviewJson(), ReviewReport.class);
501	        return new Results.FormulaView(row.id(), row.productCode(), row.productName(),
502	                row.categoryCode(), row.version(), row.state(), row.reviewPassed(), report,
503	                row.reviewedAt(), row.approvedAt(), replayed);
504	    }
505	
506	    private Results.FilingView buildFilingView(FilingRow row, boolean replayed) {
507	        Long deadline = row.watchStartDay() == null ? null
508	                : row.watchStartDay() + REVIEW_GRACE_DAYS;
509	        Long daysRemaining = deadline == null ? null
510	                : deadline - clock.todayEpochDay();
511	        Object snapshot = row.snapshot() == null ? null : JsonSupport.readTree(row.snapshot());
512	        return new Results.FilingView(row.id(), row.formulaId(), row.productCode(),
513	                row.version(), row.status(), row.watchStartDay(), deadline, daysRemaining,
514	                row.suspendReason(), snapshot, row.createdAt(), row.finalizedAt(), replayed);
515	    }
516	
517	    /**
518	     * requestId 幂等包装：指纹覆盖 requestId 与全部业务字段。
519	     * 先插入占位行（status_code=0）抢占 requestId，执行业务动作后回填首次响应；
520	     * 同键同参返回首次结果（含首次状态码），同键异参返回 409；
521	     * 业务动作抛错时外层事务回滚，占位行一并回滚，客户端可用同一 requestId 重试。
522	     */
523	    private <T> ServiceResult<T> withIdempotency(String requestId, Object params, Class<T> type,
524	            Supplier<Outcome<T>> action) {
525	        if (requestId == null || requestId.isBlank()) {
526	            throw new ApiException(HttpStatus.BAD_REQUEST, "REQUEST_ID_REQUIRED",
527	                    "变更接口必须提供 requestId");
528	        }
529	        String fingerprint = fingerprint(requestId, params);
530	        Optional<com.example.starter.compliance.repo.IdempotentRow> existing =
531	                repository.findIdempotent(requestId);
532	        if (existing.isPresent()) {
533	            return resolveIdempotent(existing.get(), fingerprint, type);
534	        }
535	        try {
536	            repository.insertIdempotent(requestId, fingerprint, 0, null, clock.nowMillis());
537	        } catch (DuplicateKeyException e) {
538	            // 并发同键：另一事务已占位或已完成，按其记录重放或报 409。
539	            com.example.starter.compliance.repo.IdempotentRow raced =
540	                    repository.findIdempotent(requestId)
541	                            .orElseThrow(() -> new ApiException(HttpStatus.CONFLICT,
542	                                    "REQUEST_IN_PROGRESS", "同一 requestId 正在处理中"));
543	            return resolveIdempotent(raced, fingerprint, type);
544	        }
545	
546	        Outcome<T> outcome = action.get();
547	        repository.completeIdempotent(requestId, outcome.status(),
548	                JsonSupport.write(outcome.body()));
549	        return new ServiceResult<>(outcome.body(), false, outcome.status());
550	    }
551	
552	    private <T> ServiceResult<T> resolveIdempotent(
553	            com.example.starter.compliance.repo.IdempotentRow row, String fingerprint,
554	            Class<T> type) {
555	        if (!row.fingerprint().equals(fingerprint)) {
556	            throw new ApiException(HttpStatus.CONFLICT, "REQUEST_PARAM_CONFLICT",
557	                    "requestId 已用于不同业务参数");
558	        }
559	        if (row.statusCode() == 0 || row.responseJson() == null) {
560	            throw new ApiException(HttpStatus.CONFLICT, "REQUEST_IN_PROGRESS",
561	                    "同一 requestId 的请求正在处理中");
562	        }
563	        return ServiceResult.replay(JsonSupport.readReplayed(row.responseJson(), type),
564	                row.statusCode());
565	    }
566	
567	    private static String fingerprint(String requestId, Object params) {
568	        Map<String, Object> material = new LinkedHashMap<>();
569	        material.put("requestId", requestId);
570	        material.put("params", params);
571	        String canonical = JsonSupport.canonical(material);
572	        try {
573	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
574	            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
575	            return HexFormat.of().formatHex(hash);
576	        } catch (NoSuchAlgorithmException e) {
577	            throw new IllegalStateException(e);
578	        }
579	    }
580	
581	    /** 业务动作结果：响应体 + 首次 HTTP 状态码（逾期自动暂停等场景首次结果即 409）。 */
582	    private record Outcome<T>(T body, int status) {
583	    }
584	}
