8	import org.springframework.transaction.annotation.Transactional;
9	
10	/**
11	 * 备案状态跃迁独立事务封装：
12	 * 逾期自动暂停必须立即生效，即使外层业务事务随后回滚（如量产上报被拒绝），
13	 * 因此使用 REQUIRES_NEW 独立提交暂停与有效位释放。
14	 */
15	@Component
16	public class FilingTransitions {
17	
18	    private final ComplianceRepository repository;
19	    private final ComplianceClock clock;
20	
21	    public FilingTransitions(ComplianceRepository repository, ComplianceClock clock) {
22	        this.repository = repository;
23	        this.clock = clock;
24	    }
25	
26	    @Transactional(propagation = Propagation.REQUIRES_NEW)
27	    public void suspendOverdueNewTransaction(FilingRow filing) {
28	        repository.markSuspended(filing.id(), "OVERDUE", clock.nowMillis());
29	        repository.releaseProduct(filing.productCode());
30	    }
31	}
