private void validateVoucher(VoucherRow voucher, LineRow line, Set<String> uncovered) {
    if (!voucher.lineCode().equals(line.lineCode())) throw 422 VOUCHER_LINE_MISMATCH;
    if (!"ISSUED".equals(voucher.status())) throw 422 VOUCHER_CONSUMED;
    if (voucher.occupancyVersion() != line.occupancyVersion()) throw 422 VOUCHER_INVALIDATED "线路随后已有量产提交，凭证失效";
    long now = clock.nowMillis();
    if (now >= voucher.confirmedAt() + VOUCHER_VALIDITY_MILLIS) throw 422 VOUCHER_EXPIRED;
    Set<String> covered = Set.copyOf(repository.findVoucherAllergens(voucher.id()));
    Set<String> missing = new TreeSet<>(uncovered); missing.removeAll(covered);
    if (!missing.isEmpty()) throw 422 VOUCHER_COVERAGE_INSUFFICIENT;
}
